            TRY(stream.seek(-1, SeekMode::FromCurrentPosition));
            TRY(read_comment(context));
            continue;
        }
        if (byte != ' ' && byte != '\t' && byte != '\n' && byte != '\r') {
            TRY(stream.seek(-1, SeekMode::FromCurrentPosition));
            if (is_first_char)
