        s = clamp(s, 0.0, 1.0);
        l = clamp(l, 0.0, 1.0);
        a = clamp(a, 0.0, 1.0);

        // HOW TO RETURN hue.to.rgb(m1, m2, h):
        auto hue_to_rgb = [](double m1, double m2, double h) -> double {
            // IF h<0: PUT h+1 IN h
            if (h < 0.0)
                h = h + 1.0;
            // IF h>1: PUT h-1 IN h
            if (h > 1.0)
                h = h - 1.0;
            // IF h*6<1: RETURN m1+(m2-m1)*h*6
            if (h * 6.0 < 1.0)
                return m1 + (m2 - m1) * h * 6.0;
            // IF h*2<1: RETURN m2
            if (h * 2.0 < 1.0)
                return m2;
            // IF h*3<2: RETURN m1+(m2-m1)*(2/3-h)*6
            if (h * 3.0 < 2.0)
                return m1 + (m2 - m1) * (2.0 / 3.0 - h) * 6.0;
            // RETURN m1
            return m1;
